import {readFileSync,writeFileSync} from 'node:fs';
import {discoverInventory,sourceHash} from '../scripts/quality-inventory';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const group=JSON.parse(readFileSync('.git/q100-extraction-group.json','utf8')) as string[];
const inputs=discoverInventory(process.cwd()).files.map(f=>({path:f.path,sourceHash:f.sourceHash}));
inputs.push({path:'src/presentation/cli/commands/sync/types.ts',sourceHash:sourceHash(readFileSync('src/presentation/cli/commands/sync/types.ts','utf8'))});
const storage=createOwnedTestDirectory('memory-q100-extraction-compat-');
try{
 const command=[process.execPath,'test','--timeout','15000',...group];
 const result=Bun.spawnSync(command,{env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 writeFileSync('.git/q100-extraction-compat.txt',output);
 for(const row of inputs)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Changed during execution '+row.path);
 writeFileSync('.git/q100-extraction-compat.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceInputs:inputs,command,exit:result.exitCode,output,source:readFileSync('.git/q100-extraction-compat.ts','utf8')},null,2)+'\n');
 console.log(output.slice(-200));if(result.exitCode!==0)throw Error('Compatibility group failed');
}finally{storage.cleanup();}

