import {crossRuntime} from "./q100-callers-cross-runtime";
import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {statfsSync} from 'node:fs';
const free=statfsSync(process.cwd());if(free.bavail*free.bsize<536870912)throw Error('Pinned runtime requires512MiB free');
import {createHash} from 'node:crypto';
import {join,dirname,delimiter} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {discoverInventory,sourceHash} from '../scripts/quality-inventory';
const storage=createOwnedTestDirectory('memory-native-compat-');
const url='https://github.com/oven-sh/bun/releases/download/bun-v1.3.14/bun-windows-x64.zip';
const digest='0a0620930b6675d7ba440e81f4e0e00d3cfbe096c4b140d3fff02205e9e18922';
const archive=join(storage.dir,'bun.zip'),destination=join(storage.dir,'runtime');
const sourcePaths=discoverInventory(process.cwd()).files.map(f=>f.path);
sourcePaths.push('src/presentation/cli/commands/sync/types.ts');
const before=sourcePaths.map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))}));
const runs:unknown[]=[];
try{
 const response=await fetch(url);if(!response.ok)throw Error('Runtime download HTTP '+response.status);
 const bytes=Buffer.from(await response.arrayBuffer());
 if(bytes.length!==38366737||createHash('sha256').update(bytes).digest('hex')!==digest)throw Error('Runtime release digest/size mismatch');
 writeFileSync(archive,bytes);mkdirSync(destination);
 const script=join(storage.dir,'expand.ps1');
 writeFileSync(script,'param([string]$Archive,[string]$Destination)\n$ErrorActionPreference = "Stop"\nExpand-Archive -LiteralPath $Archive -DestinationPath $Destination\n');
 const expanded=Bun.spawnSync(['powershell.exe','-NoProfile','-NonInteractive','-File',script,archive,destination],{stdout:'pipe',stderr:'pipe',timeout:45000});
 if(expanded.exitCode!==0)throw Error(new TextDecoder().decode(expanded.stderr));
 const executable=join(destination,'bun-windows-x64/bun.exe');if(!existsSync(executable))throw Error('Missing pinned runtime');
 const runtimeEnv={...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir};
 const inheritedPath=process.env.PATH??process.env.Path??'';
 for(const key of Object.keys(runtimeEnv))if(key.toLowerCase()==='path')delete runtimeEnv[key];
 runtimeEnv.PATH=dirname(executable)+delimiter+inheritedPath;
 const probe=Bun.spawnSync(['bun','--version'],{env:runtimeEnv,stdout:'pipe',stderr:'pipe',timeout:10000});
 if(probe.exitCode!==0||new TextDecoder().decode(probe.stdout).trim()!=='1.3.14')throw Error('Child PATH does not select pinned Bun');
 mkdirSync(join(storage.dir,"cross")); const crossRuntimeProof=await crossRuntime(executable,join(storage.dir,"cross")); const passes=Number(process.argv[2]??'1');if(!Number.isInteger(passes)||passes<1||passes>5)throw Error('Invalid bounded repeat count');
 const jsonGroup=['tests/helpers/capture-json.test.ts',...['search','context','show','list','related','stats'].map(command=>`src/presentation/cli/commands/${command}.json.test.ts`)];
 const groups=[JSON.parse(readFileSync(".git/q100-extraction-group.json","utf8"))];
 for(const group of groups){
  const command=[executable,'test','--timeout','15000',...group];
  const run=Bun.spawnSync(command,{env:runtimeEnv,stdout:'pipe',stderr:'pipe',timeout:180000});
  for(const row of before)if(sourceHash(readFileSync(row.path,'utf8'))!==row.sourceHash)throw Error('Input changed '+row.path);
  const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
  runs.push({command,exit:run.exitCode,output});
  writeFileSync('.git/q100-extraction-native.json',JSON.stringify({recordedAt:new Date().toISOString(),url,digest,bytes:bytes.length,crossRuntimeProof,runs,sourceInputs:sourcePaths.map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))})),source:readFileSync('.git/q100-extraction-native.ts','utf8')},null,2)+'\n');
  console.log(JSON.stringify({group,exit:run.exitCode,summary:output.slice(-200)}));
  if(run.exitCode!==0)throw Error('Pinned runtime group failed');
 }
}finally{storage.cleanup();}

